import unittest


def fruit_distribution(s, n):
    lis = list()
    for i in s.split(' '):
        if i.isdigit():
            lis.append(int(i))
    return n - sum(lis)


class TestFruitDistribution(unittest.TestCase):

    def test_basic_case(self):
        self.assertEqual(fruit_distribution("5 apples and 6 oranges", 19), 8)

    def test_basic_case_2(self):
        self.assertEqual(fruit_distribution("5 apples and 6 oranges", 21), 10)

    def test_zero_apples(self):
        self.assertEqual(fruit_distribution("0 apples and 1 oranges", 3), 2)

    def test_zero_oranges(self):
        self.assertEqual(fruit_distribution("1 apples and 0 oranges", 3), 2)

    def test_large_total(self):
        self.assertEqual(fruit_distribution("2 apples and 3 oranges", 100), 95)

    def test_multi_digit_numbers(self):
        self.assertEqual(fruit_distribution("100 apples and 1 oranges", 120), 19)

    def test_no_digits_in_string(self):
        self.assertEqual(fruit_distribution("apples and oranges", 10), 10)

    def test_single_fruit(self):
        self.assertEqual(fruit_distribution("0 apples and 0 oranges", 1), 1)

    def test_numbers_only(self):
        self.assertEqual(fruit_distribution("3 4", 10), 3)

    def test_negative_result(self):
        self.assertEqual(fruit_distribution("5 apples and 6 oranges", 5), -6)


if __name__ == "__main__":
    unittest.main()
